const runPickingWorkflow = async (data) => {
  return new Promise((resolve, reject) => {
    this.runWorkflow(
      "2092882318222491650",
      {
        arrayData: data,
        saveAs: "Cancelled",
        pageStatus: "Edit",
      },
      (res) => {
        console.log("Picking workflow response:", res);
        resolve(res);
      },
      (err) => {
        console.error("Failed to cancel Stock Picking:", err);
        reject(err);
      },
    );
  });
};

(async () => {
  try {
    this.showLoading();
    const allListID = "custom_41s73hyl";

    let selectedRecords;

    selectedRecords = this.getComponent(allListID)?.$refs.crud.tableSelect;

    console.log("selectedRecords", selectedRecords);

    if (selectedRecords && selectedRecords.length > 0) {
      // Only Created pickings can be cancelled
      const pickingData = selectedRecords.filter(
        (item) => item.sp_status === "Created",
      );

      if (pickingData.length === 0) {
        this.$message.error("Please select at least one created stock picking.");
        this.hideLoading();
        return;
      }

      const pickingNumbers = pickingData.map((item) => item.sp_id);

      await this.$confirm(
        `You've selected ${
          pickingNumbers.length
        } stock picking(s) to cancel. <br> <strong>Stock Picking Numbers:</strong> <br>${pickingNumbers.join(
          ", ",
        )} <br><br><strong>Warning:</strong> Cancelling will release the related stock movement back to picking and free the picking number for reuse.<br><br>Do you want to proceed?`,
        "Stock Picking Cancellation",
        {
          confirmButtonText: "Proceed",
          cancelButtonText: "Cancel",
          type: "warning",
          dangerouslyUseHTMLString: true,
        },
      ).catch(() => {
        console.log("User clicked Cancel or closed the dialog");
        throw new Error();
      });

      const results = [];

      for (const pickingItem of pickingData) {
        const id = pickingItem.id;

        const data = await db.collection("stock_picking").doc(id).get();

        if (!data.data || data.data.length === 0) {
          results.push({
            sp_id: pickingItem.sp_id,
            success: false,
            error: "Picking record not found",
          });
          continue;
        }

        try {
          const workflowResult = await runPickingWorkflow(data.data);

          if (!workflowResult || !workflowResult.data) {
            results.push({
              sp_id: pickingItem.sp_id,
              success: false,
              error: "No response from workflow",
            });
            continue;
          }

          const resultCode = workflowResult.data.code;

          // Handle 400 - General error
          if (
            resultCode === "400" ||
            resultCode === 400 ||
            workflowResult.data.success === false
          ) {
            const errorMessage =
              workflowResult.data.msg ||
              workflowResult.data.message ||
              "Failed to cancel Stock Picking";
            results.push({
              sp_id: pickingItem.sp_id,
              success: false,
              error: errorMessage,
            });
            continue;
          }

          // Handle success
          if (
            resultCode === "200" ||
            resultCode === 200 ||
            workflowResult.data.success === true
          ) {
            results.push({
              sp_id: pickingItem.sp_id,
              success: true,
            });
          } else {
            results.push({
              sp_id: pickingItem.sp_id,
              success: false,
              error: "Unknown workflow status",
            });
          }
        } catch (error) {
          results.push({
            sp_id: pickingItem.sp_id,
            success: false,
            error: error.message || "Failed to cancel",
          });
        }
      }

      // Show summary
      const successCount = results.filter((r) => r.success).length;
      const failCount = results.filter((r) => !r.success).length;

      if (failCount > 0) {
        const failedItems = results
          .filter((r) => !r.success)
          .map((r) => `${r.sp_id}: ${r.error}`)
          .join("<br>");
        this.$message.error(
          `${successCount} succeeded, ${failCount} failed:<br>${failedItems}`,
        );
      } else {
        this.$message.success(
          `All ${successCount} Stock Picking(s) cancelled successfully`,
        );
      }

      this.hideLoading();
      this.refresh();
      } else {
      this.hideLoading();
      this.$message.error("Please select at least one record.");
    }
  } catch (error) {
    this.hideLoading();
    console.error(error);
  }
})();

(async () => {
  const pickingList =
    this.getComponent("custom_41s73hyl")?.$refs.crud.tableSelect;

  console.log("pickingList", pickingList);
  const plantId = this.getVarSystem("deptIds").split(",")[0];
  let pickingIDs = [];

  if (pickingList && pickingList.length > 0) {
    pickingIDs = pickingList.map((item) => item.id);

    console.log("pickingIDs", pickingIDs);

    this.setData({
      picking_id: pickingIDs.join(","),
    });

    const resTemplateAccess = await db
      .collection("print_template_access")
      .filter([
        {
          type: "branch",
          operator: "all",
          children: [
            {
              prop: "plant_id",
              operator: "in",
              value: plantId,
            },
            {
              prop: "doc_type",
              operator: "equal",
              value: "stock_picking",
            },
          ],
        },
      ])
      .get();

    if (!resTemplateAccess || resTemplateAccess.data.length === 0) {
      this.$message.error("No print template found.");
      return;
    } else if (resTemplateAccess && resTemplateAccess.data.length === 1) {
      const templateID = resTemplateAccess.data[0].print_template_id;

      window.open(
        `/sucode/openpage/${templateID}?picking_id=${pickingIDs.join(
          ","
        )}&name=Stock Picking`
      );
    } else if (resTemplateAccess && resTemplateAccess.data.length > 1) {
      await this.openDialog("dialog_print_template");
      setTimeout(() => {
        this.setData({
          [`dialog_print_template.template_id`]: "",
          [`dialog_print_template.print_template_id`]: "",
        });

        this.setOptionData(
          `dialog_print_template.print_template_id`,
          resTemplateAccess.data
        );
      }, 50);
    }

    await this.getComponent("custom_41s73hyl")?.$refs.crud.clearSelection();
  } else {
    this.$message.error("Please select at least one record.");
  }
})();

(async () => {
  const templateID = this.getValue(`dialog_print_template.template_id`);
  const pickingID = this.getValue("picking_id");
  console.log('pickingID', pickingID)
  window.open(
    `/sucode/openpage/${templateID}?picking_id=${pickingID}&name=Stock Picking`
  );

  this.setData({
    [`dialog_print_template.template_id`]: "",
    [`dialog_print_template.print_template_id`]: "",
  });

  this.closeDialog("dialog_print_template");
})();
